(()=>{const base='/concept-traveller-stories-interactive/',supported=['en','th','es','it','de','fr','pt'];const current=document.documentElement.dataset.reportLocale||(document.documentElement.lang||'en').split('-')[0];const picker=document.querySelector('.report-language');if(!picker)return;const options=[...picker.querySelectorAll('[data-language]')];for(const b of options){const on=b.dataset.language===current;b.setAttribute('aria-selected',String(on));if(!supported.includes(b.dataset.language)){b.disabled=true;b.title='Coming soon';}if(on){const toggle=picker.querySelector('.report-language-toggle');toggle.setAttribute('aria-label',(current==='fr'?'Sélectionner une langue, ':current==='pt'?'Selecionar idioma, ':'Select language, ')+b.textContent.trim());toggle.querySelector('span').textContent=current.toUpperCase();toggle.querySelector('img').src=b.querySelector('img').src;}}document.addEventListener('click',e=>{const b=e.target.closest('[data-language]');if(!b||!supported.includes(b.dataset.language))return;e.preventDefault();e.stopImmediatePropagation();location.assign(base+(b.dataset.language==='en'?'':b.dataset.language+'/'));},true);})();
